command:
$ErrorActionPreference = "Stop"
git fetch origin main work/large-folder-name-index --no-tags --prune
if ($LASTEXITCODE -ne 0) { throw "fetch failed" }
if ((git rev-parse origin/main).Trim() -ne "6e6e1a66cf69c7158f2bfa2be329341b72d5b388") { throw "main moved" }
if ((git rev-parse origin/work/large-folder-name-index).Trim() -ne "decc89f83e34da0c94df9b861b6acbf298b84064") { throw "candidate branch moved" }
if ((git status --short).Count -ne 0) { throw "dirty persistent checkout" }
git checkout -B work/large-folder-name-index origin/work/large-folder-name-index
if ($LASTEXITCODE -ne 0) { throw "checkout candidate failed" }
if ((git rev-parse HEAD).Trim() -ne "decc89f83e34da0c94df9b861b6acbf298b84064") { throw "candidate mismatch" }
python -X utf8 -m py_compile tests\winui\test_large_owned_folder_gui.py
if ($LASTEXITCODE -ne 0) { throw "GUI harness syntax failed" }
if (!(Test-Path -LiteralPath "out\winui\Release\flyExplorer.exe" -PathType Leaf)) { throw "validated Release artifact missing" }
python -X utf8 tests\winui\test_large_owned_folder_gui.py --items 2300 --configuration Release
if ($LASTEXITCODE -ne 0) { throw "2300-item keyboard filter smoke failed" }
git diff --check origin/main..HEAD
if ($LASTEXITCODE -ne 0) { throw "diff check failed" }
Write-Host "LARGE_FOLDER_NAME_FILTER_KEYBOARD_SMOKE_PASS"
